/* Muuzee Home — page-specific JS */

const ARTISTS = (() => {
  const catalog = window.MuuzeeArtistCatalog || [];
  const featured = catalog.filter(artist => artist.featured);
  return featured.length ? featured : catalog.slice(0,8);
})();
